<script setup lang="ts">import{onMounted}from 'vue';import{releaseStore,loadReleases}from '../stores/releases';import{exportRun}from '../api/runs';import{useTask}from '../hooks/useTask';import{dateTime}from '../utils/format';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import EmptyState from '../components/common/EmptyState.vue';const{error,execute}=useTask();const refresh=()=>execute(loadReleases);const download=(id:number)=>execute(()=>exportRun(id));onMounted(refresh);</script><template><PageHeading index="05 / RELEASES" title="发布档案" subtitle="计划负责人确认后的日配参考，保留运行编号与发布说明。"/><ErrorNotice :message="error" @retry="refresh"/><EmptyState v-if="!releaseStore.items.length" title="尚无已发布建议" hint="完成一次预测后，由计划负责人在结果页确认发布。"/><article class="release" v-for="r in releaseStore.items" :key="r.id"><div class="release-number">{{String(r.id).padStart(2,'0')}}</div><div><p class="eyebrow">PUBLISHED / {{dateTime(r.published_at)}}</p><h2>预测档案 #{{r.run_id}}</h2><p>{{r.note}}</p><RouterLink :to="'/results/'+r.run_id">查看计算依据 ↗</RouterLink></div><button @click="download(r.run_id)">下载建议 CSV ↓</button></article></template>
